// Boulder Run toggle: A movie in a toggle. Flip it and the explorer outruns the boulder. Flip it back for the sequel.
// One file, no dependencies. From https://zerowing.in/toggles/
//
// Use it:
//   <script type="module" src="boulder.js"></script>
//
//   <tg-boulder style="display:block; width:360px; height:220px"></tg-boulder>
//
//   <script type="module">
//     const t = document.querySelector("tg-boulder");
//     t.addEventListener("change", (e) => console.log("on?", e.detail.checked));
//     // t.checked = true;  t.toggle();
//   </script>
//
// API: the `checked` attribute / .checked property, .toggle(), a "change" event ({detail: {checked}}).
// The switch scales to fit its box (designed at 360x220); fill="0.9" sets how much of the box it fills (default 0.82).
// The element paints its own scene background, so give it a rounded container if you want one.

// ---- shared base ----
// Shared base for every toggle in the library.
//
// Contract (every components/<id>.js follows it):
//   - `export default class extends ToggleBase` and `customElements.define('tg-<id>', …)` at the bottom.
//   - Override `template()` → HTML string for the shadow root (include its own <style>).
//     Everything is drawn inside a fixed design stage of W×H px (static W/H, default 360×220);
//     the base scales that stage to fit the host. The host itself is the full scene (paint
//     :host's background yourself if the style swaps day/night etc.).
//   - Override `render(on, instant)` → apply the on/off state. `instant` is true on first paint.
//   - Optional `tick(t, dt)` → called every animation frame while connected (t in ms, from
//     performance.now(), so a virtual clock can drive it). Return nothing.
//   - Any element with [data-hit] is the clickable switch; clicking it calls this.toggle().
//   - Time sources: only performance.now() / rAF / CSS transitions & animations. No setTimeout
//     chains for visible motion (capture seeks a virtual clock).
//
// Public API on every element: .checked (bool, reflects the `checked` attribute), .toggle(),
// 'change' event with detail {checked}. this.scale = current stage scale, this.dpr = devicePixelRatio.

class ToggleBase extends HTMLElement {
  static W = 360;
  static H = 220;
  static observedAttributes = ['checked'];

  constructor() {
    super();
    this.root = this.attachShadow({ mode: 'open' });
    this.scale = 1;
    this.dpr = Math.min(window.devicePixelRatio || 1, 2);
    this._raf = 0;
    this._last = 0;
  }

  template() { return ''; }
  render(_on, _instant) {}
  tick(_t, _dt) {}
  onResize() {}

  connectedCallback() {
    if (!this._built) {
      const { W, H } = this.constructor;
      this.root.innerHTML = `
        <style>
          :host { display: block; position: relative; overflow: hidden; contain: content; -webkit-tap-highlight-color: transparent; }
          .tg-stage { position: absolute; left: 50%; top: 50%; width: ${W}px; height: ${H}px;
            transform: translate(-50%, -50%) scale(var(--s, 1)); transform-origin: 50% 50%; }
          [data-hit] { cursor: pointer; }
        </style>
        <div class="tg-stage">${this.template()}</div>`;
      this.stage = this.root.querySelector('.tg-stage');
      this.root.addEventListener('click', (e) => {
        if (e.composedPath().some((n) => n instanceof Element && n.hasAttribute('data-hit'))) this.toggle();
      });
      this._built = true;
      this.setup?.();
      this.render(this.checked, true);
    }
    this._ro = new ResizeObserver(() => this._fit());
    this._ro.observe(this);
    this._fit();
    const loop = (t) => {
      const dt = this._last ? Math.min(t - this._last, 64) : 16;
      this._last = t;
      this.tick(t, dt);
      this._raf = requestAnimationFrame(loop);
    };
    this._raf = requestAnimationFrame(loop);
  }

  disconnectedCallback() {
    cancelAnimationFrame(this._raf);
    this._ro?.disconnect();
    this._last = 0;
  }

  _fit() {
    const { W, H } = this.constructor;
    const r = this.getBoundingClientRect();
    if (!r.width || !r.height) return;
    // Toggle fills ~78% of the shorter fit so every tile has breathing room.
    this.scale = Math.min(r.width / W, r.height / H) * (parseFloat(this.getAttribute('fill')) || 0.82);
    this.style.setProperty('--s', this.scale);
    this.onResize();
  }

  get checked() { return this.hasAttribute('checked'); }
  set checked(v) { this.toggleAttribute('checked', !!v); }

  attributeChangedCallback(name, oldV, newV) {
    if (name === 'checked' && this._built && (oldV === null) !== (newV === null)) {
      this.render(this.checked, false);
      this.dispatchEvent(new CustomEvent('change', { detail: { checked: this.checked }, bubbles: true }));
    }
  }

  toggle() { this.checked = !this.checked; }

  $(sel) { return this.root.querySelector(sel); }
  $$(sel) { return [...this.root.querySelectorAll(sel)]; }

  // Size a <canvas> to cover `w×h` design px at full device resolution.
  sizeCanvas(cv, w, h) {
    const k = this.scale * this.dpr;
    cv.width = Math.max(1, Math.round(w * k));
    cv.height = Math.max(1, Math.round(h * k));
    cv.style.width = w + 'px';
    cv.style.height = h + 'px';
    const ctx = cv.getContext('2d');
    ctx.setTransform(k, 0, 0, k, 0, 0);
    return ctx;
  }
}

// Easing helpers shared by components.
const ease = {
  outCubic: (x) => 1 - Math.pow(1 - x, 3),
  inOutCubic: (x) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2),
  outBack: (x, s = 1.70158) => 1 + (s + 1) * Math.pow(x - 1, 3) + s * Math.pow(x - 1, 2),
  // Critically-damped-ish spring step: returns new [pos, vel].
  spring: (pos, vel, target, dt, k = 170, d = 18) => {
    const s = dt / 1000;
    const a = -k * (pos - target) - d * vel;
    vel += a * s;
    pos += vel * s;
    return [pos, vel];
  },
};

const clamp = (v, a = 0, b = 1) => Math.min(b, Math.max(a, v));

// ---- Boulder Run ----
// Boulder Run — a little adventure movie inside a toggle.
// Off → On  = Scene 1 "The Idol": the explorer lifts the idol, the boulder (the knob) rolls, he sprints and dives out.
// On → Off  = Scene 2 "The Sequel": he walks back in and pushes the boulder all the way home, catches his hat,
//             puts the idol back and dusts off his hands.
// Everything is a pure function of scene time s, so any frame can be seeked. Clicking mid-scene fast-forwards
// the running scene, then plays the next one.

const TW = 300, TH = 130;          // inner window (design px) — matches Snow Globe
const BR = 56;                     // boulder radius (112 knob)
const BY = TH / 2;                 // boulder centre y
const G = BY + BR;                 // floor line
const LX = 9 + BR, RX = TW - 9 - BR; // boulder slots
const NX = 150;                    // niche / idol x
const NY = 66;                     // niche ledge top
const STX = LX + 79;               // where he stands after pushing the boulder home
const D1 = 2.35, D2 = 2.8;         // scene lengths (s)
const TAU = Math.PI * 2;
const EX = 1.75;                   // explorer scale (~58 px tall)
const KS = EX / 1.2;               // stride / spacing factor vs the original 1.2 rig
const HAT_A = -0.45;               // where the hat sits on the boulder (angle from top)
const TORCHES = [{ x: 75, y: 40 }, { x: 225, y: 40 }];

const hash = (i) => { const x = Math.sin(i * 127.1 + 311.7) * 43758.5453; return x - Math.floor(x); };
const seg = (s, a, b) => clamp((s - a) / (b - a));
const eo = ease.outCubic, eio = ease.inOutCubic;

// ---------- explorer poses ----------
// Angles are from straight down, positive = toward facing. legs: [thigh, knee bend], arms: [upper, elbow bend].
const P = (o) => Object.assign({
  x: NX, dir: 1, lean: 0.04, lift: 0, rot: 0, tilt: 0,
  legs: [[0.07, 0.06], [-0.07, 0.06]], arms: [[0.15, 0.3], [-0.1, 0.3]],
  hat: true, idol: false, mark: 0,
}, o);

function lerpPose(a, b, k) {
  const L = (u, v) => u + (v - u) * k;
  return {
    ...(k < 0.5 ? a : b),
    x: L(a.x, b.x), lean: L(a.lean, b.lean), lift: L(a.lift, b.lift), rot: L(a.rot, b.rot), tilt: L(a.tilt, b.tilt),
    legs: a.legs.map((l, i) => [L(l[0], b.legs[i][0]), L(l[1], b.legs[i][1])]),
    arms: a.arms.map((l, i) => [L(l[0], b.arms[i][0]), L(l[1], b.arms[i][1])]),
  };
}

const stand = (t, x = NX, dir = 1, o = {}) => P({
  x, dir, lift: 0.35 * Math.sin(t * 0.0024), tilt: 0.04 * Math.sin(t * 0.0013),
  arms: [[0.12 + 0.04 * Math.sin(t * 0.0024), 0.3], [-0.12, 0.3]], ...o,
});
const CROUCH = P({ lean: 0.24, lift: 2.6, legs: [[0.5, 1.0], [-0.02, 0.8]], arms: [[-0.4, 0.6], [-0.6, 0.5]], tilt: 0.12 });
const REACH = P({ lean: -0.06, lift: -1.5, legs: [[0.03, 0], [-0.03, 0]], arms: [[3.02, 0.04], [-0.3, 0.25]], tilt: -0.5 });
const HOLD = P({ lean: -0.1, lift: -0.4, legs: [[0.14, 0.1], [-0.1, 0.05]], arms: [[2.8, 0.15], [0.55, 2.0]], tilt: -0.25, idol: true });

const runLeg = (q) => [0.8 * Math.sin(q), 0.25 + 1.25 * Math.max(0, Math.cos(q))];
const pushLeg = (q) => [0.5 * Math.sin(q) - 0.38, 0.2 + 0.95 * Math.max(0, Math.cos(q))];
const walkLeg = (q) => [0.45 * Math.sin(q), 0.15 + 0.7 * Math.max(0, Math.cos(q))];

// Scene 1 — The Idol
function exp1(s, t) {
  const st = stand(t);
  if (s < 0.12) return st;
  if (s < 0.22) return lerpPose(st, CROUCH, eo(seg(s, 0.12, 0.22)));
  if (s < 0.36) return lerpPose(CROUCH, REACH, ease.outBack(seg(s, 0.22, 0.36), 1.3));
  if (s < 0.5) return { ...lerpPose(REACH, HOLD, eio(seg(s, 0.36, 0.5))), idol: true };
  if (s < 0.58) return { ...HOLD, tilt: -0.22 + 0.07 * Math.sin(s * 90) };
  if (s < 0.72) {
    const k = seg(s, 0.58, 0.72);
    return P({ dir: -1, lean: -0.28, lift: -7.5 * Math.sin(Math.PI * k), legs: [[0.6, 1.2], [-0.12, 0.95]],
      arms: [[2.6, 0.3], [2.15, 0.5]], tilt: -0.1, idol: true, mark: 1 });
  }
  if (s < 1.45) {
    const k = seg(s, 0.72, 1.45);
    const x = NX + 135 * Math.pow(k, 1.25);
    const ph = (x - NX) / (7.8 * KS) + 0.6;
    return P({ x, lean: 0.32, lift: 0.6 - 1.9 * Math.abs(Math.cos(ph)), legs: [runLeg(ph), runLeg(ph + Math.PI)],
      arms: [[1.15, 1.7], [-0.95 * Math.sin(ph) + 0.1, 1.25]], tilt: 0.05, idol: true, mark: s < 0.82 ? 1 : 0 });
  }
  if (s < 1.8) {
    const k = seg(s, 1.45, 1.8);
    return P({ x: 285 + 70 * k, lean: 0.3, rot: 1.25 * eo(Math.min(1, k * 1.5)),
      lift: -9 * Math.sin(Math.PI * k) + 8 * k * k, legs: [[-0.15, 0.3], [-0.5, 0.6]],
      arms: [[2.75, 0.05], [2.55, 0.1]], tilt: -0.3, idol: true, hat: s < 1.52 });
  }
  return null;
}

// Scene 2 — The Sequel
const PUSH_DX = 79;
function pushPose(x, o = {}) {
  const ph = (400 - x) / (6 * KS);
  return P({ x, dir: -1, lean: 0.78, lift: 1.4 + 0.8 * Math.abs(Math.sin(ph)), legs: [pushLeg(ph), pushLeg(ph + Math.PI)],
    arms: [[1.5, 0.15], [1.38, 0.3]], tilt: 0.22, hat: false, ...o });
}
function exp2(s, t, bx) {
  if (s < 0.3) {
    const k = seg(s, 0, 0.3);
    const x = bx + PUSH_DX + 40 * (1 - eo(k));
    return pushPose(x, { lean: 0.35 + 0.43 * k, arms: [[1.0 + 0.5 * k, 0.4], [0.8 + 0.58 * k, 0.5]] });
  }
  if (s < 1.6) return pushPose(bx + PUSH_DX);
  const STANDL = stand(t, STX, -1, { hat: false });
  if (s < 1.85) return lerpPose(pushPose(LX + PUSH_DX), STANDL, eo(seg(s, 1.6, 1.85)));
  const LOOK = P({ x: STX, dir: -1, hat: false, tilt: -0.6, lean: -0.1, arms: [[0.7, 0.9], [0.5, 0.9]] });
  if (s < 2.05) return lerpPose(STANDL, LOOK, eo(seg(s, 1.85, 1.97)));
  if (s < 2.17) {
    const k = seg(s, 2.05, 2.17);
    return { ...lerpPose(LOOK, STANDL, eo(k)), hat: true, lift: 2 * Math.sin(Math.PI * k) };
  }
  if (s < 2.4) {
    const k = eio(seg(s, 2.17, 2.4));
    const x = STX + (NX - STX) * k;
    const ph = k * 3 * Math.PI;
    return P({ x, legs: [walkLeg(ph), walkLeg(ph + Math.PI)], arms: [[-0.35 * Math.sin(ph), 0.35], [0.35 * Math.sin(ph), 0.35]],
      lift: 0.4 - 0.8 * Math.abs(Math.cos(ph)) });
  }
  const st = stand(t);
  if (s < 2.5) return { ...lerpPose(st, REACH, eo(seg(s, 2.4, 2.5))), idol: true };
  if (s < 2.62) return lerpPose(REACH, st, eio(seg(s, 2.5, 2.62)));
  if (s < 2.8) {
    const w = Math.sin(s * 70);
    const dust = P({ arms: [[0.95 + 0.14 * w, 1.3], [0.85 - 0.14 * w, 1.3]], tilt: 0.14, lean: 0.06 });
    return lerpPose(dust, st, seg(s, 2.74, 2.8));
  }
  return st;
}

// ---------- boulder ----------
function boulder1(s) {
  if (s < 0.44) return [LX, BY];
  if (s < 0.5) return [LX + 1.1 * Math.sin((s - 0.44) * 130), BY];
  if (s < 1.88) return [LX + (RX - LX) * Math.pow(seg(s, 0.5, 1.88), 1.15), BY];
  return [RX - 5 * Math.sin(Math.PI * seg(s, 1.88, 2.08)), BY - 2.5 * Math.sin(Math.PI * seg(s, 1.88, 2.0))];
}
function boulder2(s) {
  if (s < 0.3) return [RX, BY];
  if (s < 0.4) return [RX - 2.5 * Math.sin(Math.PI * seg(s, 0.3, 0.4)), BY];
  if (s < 1.6) {
    const u = eio(seg(s, 0.4, 1.6));
    const g = u - (Math.sin(TAU * 6 * u) / (TAU * 6)) * 0.75;   // surges, one per heave
    return [RX - (RX - LX) * g, BY];
  }
  return [LX, BY];
}

function headPos(p) {
  const hy = G + EX * (-14 + p.lift);
  const sx = 10 * Math.sin(p.lean), sy = -10 * Math.cos(p.lean);
  return [p.x + EX * p.dir * (sx + 5 * Math.sin(p.lean)), hy + EX * (sy - 5 * Math.cos(p.lean))];
}

// World state for a scene at time s. scene 0 = resting.
function world(scene, s, t) {
  const w = { shake: 0, idolNiche: false, hat: null, exp: null };
  if (scene === 1) {
    [w.bx, w.by] = boulder1(s);
    w.exp = exp1(s, t);
    w.idolNiche = s < 0.36;
    if (s < 0.44) w.shake = 0;
    else if (s < 0.82) w.shake = 0.9;
    if (s >= 1.88) w.shake = 3.4 * Math.exp(-(s - 1.88) * 10);
    if (s >= 1.52 && s < 2.1) {
      const tau = s - 1.52, T = 0.58, g = 700, y0 = 62, y1 = BY - BR * Math.cos(HAT_A), vy = (y1 - y0 - 0.5 * g * T * T) / T;
      const x1 = RX + BR * Math.sin(HAT_A);
      w.hat = { x: 298 + (x1 - 298) * (tau / T), y: y0 + vy * tau + 0.5 * g * tau * tau, rot: HAT_A - 2 * TAU * (1 - tau / T) };
    } else if (s >= 2.1) {
      const k = seg(s, 2.1, 2.35);
      w.hat = { x: w.bx + BR * Math.sin(HAT_A), y: w.by - BR * Math.cos(HAT_A) - 3 * Math.sin(Math.PI * k) * (1 - k), rot: HAT_A + 0.25 * Math.sin(k * 9) * (1 - k), squash: k < 0.2 ? 1 - k * 2 : 0 };
    }
  } else {
    [w.bx, w.by] = boulder2(s);
    w.exp = exp2(s, t, w.bx);
    w.idolNiche = s >= 2.5;
    w.shake = s > 0.4 && s < 1.6 ? 0.35 : 0;
    if (s < 1.72) {
      const pushing = s > 0.3 && s < 1.6 ? 1 : 0;
      w.hat = { x: w.bx + BR * Math.sin(HAT_A) + 1.5 * Math.sin(s * 9) * pushing, y: w.by - BR * Math.cos(HAT_A) - Math.abs(Math.sin(s * 13)) * 2.2 * pushing, rot: HAT_A + 0.2 * Math.sin(s * 7) * pushing };
    } else if (s < 2.05) {
      const k = eio(seg(s, 1.72, 2.05)), u = 1 - k;
      const hp = headPos(P({ x: STX, dir: -1 }));
      const p0 = [LX + BR * Math.sin(HAT_A), BY - BR * Math.cos(HAT_A)], p1 = [LX + 45, -10], p2 = [hp[0], hp[1] - 2.2 * EX];
      w.hat = { x: u * u * p0[0] + 2 * u * k * p1[0] + k * k * p2[0], y: u * u * p0[1] + 2 * u * k * p1[1] + k * k * p2[1], rot: HAT_A * (1 - k) + TAU * k };
    }
  }
  w.rot = (w.bx - LX) / BR;
  return w;
}

// ---------- drawing ----------
function drawHat(ctx, x, y, rot, sq = 0, sc = 1) {
  ctx.save();
  ctx.translate(x, y); ctx.rotate(rot); ctx.scale(sc * (1 + sq * 0.15), sc * (1 - sq * 0.2));
  ctx.fillStyle = '#7a4e2a';
  ctx.beginPath(); ctx.ellipse(0, 0, 6.2, 1.3, 0, 0, TAU); ctx.fill();
  ctx.beginPath(); ctx.moveTo(-3.6, 0); ctx.quadraticCurveTo(-3.8, -4.6, -0.6, -4.9); ctx.quadraticCurveTo(0, -4.2, 0.6, -4.9);
  ctx.quadraticCurveTo(3.8, -4.6, 3.6, 0); ctx.closePath(); ctx.fill();
  ctx.fillStyle = '#2a170b'; ctx.fillRect(-3.6, -1.6, 7.2, 1.2);
  ctx.fillStyle = 'rgba(255,220,170,.25)'; ctx.fillRect(-3, -4.2, 2.2, 0.7);
  ctx.restore();
}

function drawIdol(ctx, x, y, glint = 0, sc = 1) {
  ctx.save(); ctx.translate(x, y); ctx.scale(sc, sc);
  const g = ctx.createLinearGradient(-3, -11, 3, 0);
  g.addColorStop(0, '#fff2a8'); g.addColorStop(0.45, '#f2b632'); g.addColorStop(1, '#8a5a12');
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.moveTo(-3, 0); ctx.lineTo(-2.2, -5.5); ctx.lineTo(2.2, -5.5); ctx.lineTo(3, 0); ctx.closePath(); ctx.fill();
  ctx.beginPath(); ctx.ellipse(0, -8.2, 2.6, 3, 0, 0, TAU); ctx.fill();
  ctx.fillStyle = '#5a3a0a'; ctx.fillRect(-1.3, -8.8, 0.8, 0.8); ctx.fillRect(0.5, -8.8, 0.8, 0.8);
  if (glint > 0) {
    ctx.globalAlpha = glint; ctx.fillStyle = '#fff';
    ctx.translate(1.5, -9);
    ctx.beginPath(); ctx.moveTo(0, -5); ctx.lineTo(0.7, -0.7); ctx.lineTo(5, 0); ctx.lineTo(0.7, 0.7); ctx.lineTo(0, 5);
    ctx.lineTo(-0.7, 0.7); ctx.lineTo(-5, 0); ctx.lineTo(-0.7, -0.7); ctx.closePath(); ctx.fill();
  }
  ctx.restore();
}

function drawExplorer(ctx, p) {
  // ground shadow
  const air = clamp(-p.lift / 14);
  ctx.fillStyle = `rgba(10,5,2,${0.45 * (1 - air * 0.6)})`;
  ctx.beginPath(); ctx.ellipse(p.x, G + 0.8, 7.5 * KS * (1 - air * 0.3), 2.2, 0, 0, TAU); ctx.fill();

  for (const outline of [true, false]) {
    ctx.save();
    ctx.translate(p.x, G); ctx.scale(EX * p.dir, EX); ctx.translate(0, -14 + p.lift); ctx.rotate(p.rot);
    ctx.lineCap = 'round'; ctx.lineJoin = 'round';
    const O = outline ? 1.7 : 0;
    const col = (c) => (outline ? 'rgba(18,9,4,.9)' : c);
    const limb = (ax, ay, a1, a2, l1, l2, w, c) => {
      const kx = ax + l1 * Math.sin(a1), ky = ay + l1 * Math.cos(a1);
      const ex = kx + l2 * Math.sin(a2), ey = ky + l2 * Math.cos(a2);
      ctx.strokeStyle = col(c); ctx.lineWidth = w + O;
      ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(kx, ky); ctx.lineTo(ex, ey); ctx.stroke();
      return [ex, ey];
    };
    const sx = 10 * Math.sin(p.lean), sy = -10 * Math.cos(p.lean);
    const leg = ([th, kn], c) => {
      const a2 = th - kn;
      const [fx, fy] = limb(0, 0, th, a2, 7, 7, 3.3, c);
      ctx.strokeStyle = col('#24160c'); ctx.lineWidth = 3.3 + O;
      ctx.beginPath(); ctx.moveTo(fx, fy); ctx.lineTo(fx + 2.6 * Math.cos(a2), fy - 2.6 * Math.sin(a2)); ctx.stroke();
    };
    const arm = ([up, el], c, hasIdol) => {
      const [hx, hy] = limb(sx, sy + 1, up, up + el, 6.5, 6, 2.6, c);
      ctx.fillStyle = col('#e0a678');
      ctx.beginPath(); ctx.arc(hx, hy, 1.4 + O / 2, 0, TAU); ctx.fill();
      if (hasIdol && !outline) drawIdol(ctx, hx, hy + 1.5, 0);
    };
    arm(p.arms[1], '#a8875a', false);
    leg(p.legs[1], '#4e3220');
    // satchel
    ctx.fillStyle = col('#5a361b');
    ctx.save(); ctx.rotate(p.lean); ctx.beginPath(); ctx.roundRect(-5.2 - O / 2, -4.5 - O / 2, 4.2 + O, 4.6 + O, 1); ctx.fill(); ctx.restore();
    // torso
    ctx.strokeStyle = col('#d8b47a'); ctx.lineWidth = 5.4 + O;
    ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(sx, sy); ctx.stroke();
    if (!outline) {
      ctx.strokeStyle = '#4a2c14'; ctx.lineWidth = 0.9;
      ctx.beginPath(); ctx.moveTo(sx + 1.6 * Math.cos(p.lean), sy + 1.6 * Math.sin(p.lean)); ctx.lineTo(-2.2, -1.6); ctx.stroke();
      ctx.strokeStyle = '#6a4528'; ctx.lineWidth = 5.4;
      ctx.beginPath(); ctx.moveTo(0, 0.6); ctx.lineTo(0.6 * Math.sin(p.lean), -1.2); ctx.stroke();
    }
    // head
    ctx.save();
    ctx.translate(sx + 5 * Math.sin(p.lean), sy - 5 * Math.cos(p.lean));
    ctx.rotate(p.lean + p.tilt);
    ctx.fillStyle = col('#e0a678');
    ctx.beginPath(); ctx.arc(0, 0, 3.8 + O / 2, 0, TAU); ctx.fill();
    if (!outline) {
      ctx.fillStyle = '#3a2412'; ctx.beginPath(); ctx.arc(-1.2, 0.6, 2.9, Math.PI * 0.55, Math.PI * 1.25); ctx.fill();
      ctx.fillStyle = '#1a0e06'; ctx.fillRect(1.6, -0.9, 0.9, 1.1);
      if (p.hat) drawHat(ctx, 0, -2.2, 0);
    } else if (p.hat) {
      ctx.fillStyle = col(''); ctx.beginPath(); ctx.ellipse(0, -2.2, 7, 2, 0, 0, TAU); ctx.fill();
      ctx.beginPath(); ctx.roundRect(-4.4, -8, 8.8, 6.5, 2.5); ctx.fill();
    }
    ctx.restore();
    leg(p.legs[0], '#6a4528');
    arm(p.arms[0], '#d8b47a', p.idol);
    ctx.restore();
  }
}

// Static boulder surface features, in boulder-local coords.
const CRATERS = Array.from({ length: 8 }, (_, i) => ({ a: hash(i) * TAU, r: 8 + hash(i + 20) * 30, s: 3 + hash(i + 40) * 6.5 }));
const CRACKS = Array.from({ length: 4 }, (_, i) => {
  const a = hash(i + 60) * TAU; let r = 10 + hash(i + 70) * 22, x = Math.cos(a) * r, y = Math.sin(a) * r;
  const pts = [[x, y]];
  for (let j = 0; j < 4; j++) { x += (hash(i * 9 + j) - 0.5) * 12; y += (hash(i * 7 + j + 3) - 0.5) * 12; pts.push([x, y]); }
  return pts;
});
const SPECKS = Array.from({ length: 60 }, (_, i) => ({ a: hash(i + 100) * TAU, r: Math.sqrt(hash(i + 200)) * 44, l: hash(i + 300) > 0.5 }));

function drawBoulder(ctx, x, y, rot) {
  // light from the nearest torch
  let best = null, bd = 1e9;
  for (const tch of TORCHES) { const d = Math.hypot(tch.x - x, tch.y - y); if (d < bd) { bd = d; best = tch; } }
  let lx = best.x - x, ly = best.y - y - 30; const ll = Math.hypot(lx, ly) || 1; lx /= ll; ly /= ll;

  ctx.fillStyle = 'rgba(8,4,2,.6)';
  ctx.beginPath(); ctx.ellipse(x, G + 1, BR * 0.9, 4, 0, 0, TAU); ctx.fill();

  ctx.save(); ctx.translate(x, y);
  ctx.beginPath(); ctx.arc(0, 0, BR, 0, TAU);
  ctx.fillStyle = '#5c4a3a'; ctx.fill();
  ctx.save(); ctx.clip(); ctx.rotate(rot);
  // big tonal blotches so the roll reads
  ctx.fillStyle = 'rgba(40,28,18,.28)';
  ctx.beginPath(); ctx.ellipse(-14, 10, 26, 18, 0.6, 0, TAU); ctx.fill();
  ctx.fillStyle = 'rgba(200,170,130,.12)';
  ctx.beginPath(); ctx.ellipse(16, -14, 18, 12, -0.4, 0, TAU); ctx.fill();
  for (const sp of SPECKS) {
    ctx.fillStyle = sp.l ? 'rgba(220,195,160,.22)' : 'rgba(30,20,12,.3)';
    ctx.fillRect(Math.cos(sp.a) * sp.r, Math.sin(sp.a) * sp.r, 1.1, 1.1);
  }
  for (const c of CRATERS) {   // chipped facets
    const cx = Math.cos(c.a) * c.r, cy = Math.sin(c.a) * c.r;
    ctx.beginPath();
    for (let j = 0; j < 5; j++) {
      const a = c.a + (j / 5) * TAU, r = c.s * (0.6 + hash(j + c.s * 10) * 0.6);
      j ? ctx.lineTo(cx + Math.cos(a) * r, cy + Math.sin(a) * r) : ctx.moveTo(cx + Math.cos(a) * r, cy + Math.sin(a) * r);
    }
    ctx.closePath();
    ctx.fillStyle = 'rgba(28,19,12,.4)'; ctx.fill();
    ctx.strokeStyle = 'rgba(215,185,150,.16)'; ctx.lineWidth = 0.7; ctx.stroke();
  }
  ctx.strokeStyle = 'rgba(25,15,8,.6)'; ctx.lineWidth = 1;
  for (const cr of CRACKS) { ctx.beginPath(); cr.forEach(([a, b], j) => (j ? ctx.lineTo(a, b) : ctx.moveTo(a, b))); ctx.stroke(); }
  ctx.restore();
  // lighting (world space — does not rotate)
  const g = ctx.createRadialGradient(lx * BR * 0.45, ly * BR * 0.45, 3, 0, 0, BR * 1.04);
  g.addColorStop(0, 'rgba(255,205,150,.36)'); g.addColorStop(0.35, 'rgba(255,180,120,.06)');
  g.addColorStop(0.7, 'rgba(25,12,5,.42)'); g.addColorStop(1, 'rgba(8,4,2,.9)');
  ctx.fillStyle = g; ctx.beginPath(); ctx.arc(0, 0, BR, 0, TAU); ctx.fill();
  const la = Math.atan2(ly, lx);
  ctx.strokeStyle = 'rgba(255,190,120,.35)'; ctx.lineWidth = 1.4;
  ctx.beginPath(); ctx.arc(0, 0, BR - 0.8, la - 0.7, la + 0.7); ctx.stroke();
  ctx.restore();
}

function buildWall(k) {
  const cv = document.createElement('canvas');
  cv.width = Math.round(TW * k); cv.height = Math.round(TH * k);
  const c = cv.getContext('2d'); c.setTransform(k, 0, 0, k, 0, 0);
  c.fillStyle = '#1e120a'; c.fillRect(0, 0, TW, TH);
  let row = 0;
  for (let y = 3; y < G; y += 13, row++) {
    let x = row % 2 ? -14 : -2, i = 0;
    while (x < TW) {
      const w = 24 + hash(row * 31 + i) * 18;
      const L = 17 + hash(row * 17 + i * 3) * 8 - (y < 20 ? 4 : 0);
      c.fillStyle = `hsl(26, 34%, ${L}%)`;
      c.fillRect(x + 0.7, y + 0.7, w - 1.4, 11.6);
      c.fillStyle = 'rgba(255,215,165,.07)'; c.fillRect(x + 0.7, y + 0.7, w - 1.4, 1);
      c.fillStyle = 'rgba(0,0,0,.22)'; c.fillRect(x + 0.7, y + 11.3, w - 1.4, 1);
      if (hash(row * 13 + i * 7) > 0.78) {  // carved glyph
        c.strokeStyle = 'rgba(15,8,4,.45)'; c.lineWidth = 0.8;
        const gx = x + w / 2, gy = y + 6.5, kind = Math.floor(hash(row + i * 5) * 3);
        c.beginPath();
        if (kind === 0) { c.arc(gx, gy, 2.6, 0, TAU); c.moveTo(gx, gy - 4); c.lineTo(gx, gy + 4); }
        else if (kind === 1) { c.moveTo(gx - 3, gy + 3); c.lineTo(gx, gy - 3); c.lineTo(gx + 3, gy + 3); c.moveTo(gx - 2, gy + 1); c.lineTo(gx + 2, gy + 1); }
        else { c.moveTo(gx - 3, gy - 2); c.lineTo(gx + 3, gy - 2); c.moveTo(gx - 3, gy + 2); c.lineTo(gx + 3, gy + 2); c.moveTo(gx, gy - 3); c.lineTo(gx, gy + 3); }
        c.stroke();
      }
      x += w; i++;
    }
  }
  for (let i = 0; i < 700; i++) {
    c.fillStyle = hash(i + 900) > 0.5 ? 'rgba(255,220,180,.05)' : 'rgba(0,0,0,.14)';
    c.fillRect(hash(i) * TW, hash(i + 500) * G, 0.8, 0.8);
  }
  // niche (sized for the EX-scaled idol)
  const NT = NY - 22, NB = NY + 6, NR = 15;
  c.save();
  c.beginPath(); c.moveTo(NX - NR, NB); c.lineTo(NX - NR, NT); c.arc(NX, NT, NR, Math.PI, 0); c.lineTo(NX + NR, NB); c.closePath();
  c.fillStyle = '#2a1a10'; c.fill();
  c.clip();
  const ng = c.createLinearGradient(0, NT - NR, 0, NB); ng.addColorStop(0, '#0e0805'); ng.addColorStop(1, '#2c1b10');
  c.fillStyle = ng; c.fillRect(NX - NR - 1, NT - NR - 1, NR * 2 + 2, NB - NT + NR + 2);
  c.fillStyle = 'rgba(0,0,0,.5)'; c.fillRect(NX - NR - 1, NT - NR - 1, NR * 2 + 2, 4);
  c.restore();
  c.strokeStyle = 'rgba(255,210,160,.12)'; c.lineWidth = 1;
  c.beginPath(); c.moveTo(NX + NR + 0.5, NB); c.lineTo(NX + NR + 0.5, NT); c.arc(NX, NT, NR + 0.5, 0, -Math.PI * 0.5, true); c.stroke();
  c.fillStyle = '#6b4d33'; c.fillRect(NX - 13, NY, 26, 6);
  c.fillStyle = 'rgba(255,220,170,.22)'; c.fillRect(NX - 13, NY, 26, 1);
  c.fillStyle = 'rgba(0,0,0,.35)'; c.fillRect(NX - 13, NY + 5, 26, 1);
  // torch brackets
  for (const t of TORCHES) {
    c.fillStyle = '#1a120c'; c.fillRect(t.x - 3, t.y + 15, 6, 3);
    c.strokeStyle = '#3a2614'; c.lineWidth = 2.4; c.lineCap = 'round';
    c.beginPath(); c.moveTo(t.x, t.y + 16); c.lineTo(t.x, t.y + 5); c.stroke();
    c.fillStyle = '#20150d'; c.beginPath(); c.moveTo(t.x - 3, t.y + 3); c.lineTo(t.x + 3, t.y + 3); c.lineTo(t.x + 1.6, t.y + 7); c.lineTo(t.x - 1.6, t.y + 7); c.fill();
  }
  // floor
  const fg = c.createLinearGradient(0, G, 0, TH); fg.addColorStop(0, '#3b2717'); fg.addColorStop(1, '#140c06');
  c.fillStyle = fg; c.fillRect(0, G, TW, TH - G);
  c.fillStyle = 'rgba(255,205,150,.28)'; c.fillRect(0, G, TW, 0.8);
  c.fillStyle = 'rgba(0,0,0,.35)';
  for (let x = 8; x < TW; x += 38) c.fillRect(x, G + 1, 0.8, TH - G);
  return cv;
}

function buildNoise() {
  return Array.from({ length: 4 }, () => {
    const cv = document.createElement('canvas'); cv.width = cv.height = 128;
    const c = cv.getContext('2d'), im = c.createImageData(128, 128);
    for (let i = 0; i < im.data.length; i += 4) { const v = Math.random() * 255; im.data[i] = im.data[i + 1] = im.data[i + 2] = v; im.data[i + 3] = 255; }
    c.putImageData(im, 0, 0); return cv;
  });
}

const flicker = (t, i = 0) => 0.82 + 0.08 * Math.sin(t * 0.013 + i * 2) + 0.06 * Math.sin(t * 0.031 + 1 + i) + 0.04 * Math.sin(t * 0.071 + 2 + i * 3);

export default class Boulder extends ToggleBase {
  static W = 360;
  static H = 220;

  template() {
    return `
      <style>
        :host { background: radial-gradient(ellipse 70% 60% at 50% 48%, #2b1c12 0%, #120b07 58%, #060403 100%); }
        .sg { position: absolute; left: 15px; top: 30px; width: 330px; height: 160px; border-radius: 80px; }
        .glow { position: absolute; left: 34px; right: 34px; bottom: -30px; height: 70px; border-radius: 50%;
          background: radial-gradient(closest-side, rgba(255,140,50,.28), rgba(255,120,40,0)); filter: blur(10px); }
        /* carved bronze-and-sandstone bezel, Snow Globe's 15 px frame recipe */
        .bezel { position: absolute; inset: 0; border-radius: 80px;
          background:
            radial-gradient(120% 90% at 30% 10%, rgba(255,214,150,.22), transparent 55%),
            repeating-linear-gradient(90deg, rgba(0,0,0,0) 0 22px, rgba(0,0,0,.16) 22px 23px),
            linear-gradient(180deg, #8a6440 0%, #64462b 45%, #3f2a18 100%);
          box-shadow: 0 26px 44px -20px rgba(0,0,0,.9), 0 8px 16px -8px rgba(0,0,0,.7),
            inset 0 2px 1px rgba(255,222,170,.55), inset 0 -4px 8px rgba(0,0,0,.45), 0 0 0 1px rgba(0,0,0,.6); }
        .bezel::before { content: ''; position: absolute; inset: 5px; border-radius: 75px; pointer-events: none;
          border: 1px solid rgba(255,206,140,.18); box-shadow: inset 0 0 0 1px rgba(0,0,0,.25); }
        .win { position: absolute; left: 15px; top: 15px; width: ${TW}px; height: ${TH}px; border-radius: 65px; overflow: hidden; background: #000; }
        .win canvas { position: absolute; left: 0; top: 0; }
        .lip { position: absolute; inset: 0; border-radius: 65px; pointer-events: none;
          box-shadow: inset 0 6px 9px rgba(0,0,0,.55), inset 0 -2px 3px rgba(255,210,150,.14), inset 0 0 0 1.5px rgba(0,0,0,.4); }
        .slate { position: absolute; left: 62px; top: 12px; display: flex; align-items: center; gap: 7px; opacity: 0;
          font: 700 9px/1 "Courier New", ui-monospace, monospace; letter-spacing: .2em; color: #ead9b6; white-space: nowrap; }
        .slate i { width: 22px; height: 11px; border-radius: 2px; background: repeating-linear-gradient(-45deg, #f3eee4 0 3px, #111 3px 6px);
          box-shadow: 0 0 0 1px rgba(0,0,0,.6); }
        .slate span { color: #f2b632; }
        .slate b { font-weight: 400; color: rgba(234,217,182,.7); }
      </style>
      <div class="slate"><i></i><span>SCENE 1</span><b>THE IDOL</b></div>
      <div class="sg" data-hit>
        <div class="glow"></div><div class="bezel"></div>
        <div class="win"><canvas></canvas><div class="lip"></div></div>
      </div>`;
  }

  setup() {
    this.cv = this.$('canvas');
    this.slate = this.$('.slate');
    this.slateN = this.$('.slate span');
    this.slateT = this.$('.slate b');
    this.noise = buildNoise();
    this.scene = 0; this.s = 0; this.since = 99;
    this.pos = this.checked ? 1 : 0;
    this.target = this.pos;
  }

  onResize() {
    this.ctx = this.sizeCanvas(this.cv, TW, TH);
    this.k = this.scale * this.dpr;
    this.wall = buildWall(this.k);
    this.pats = this.noise.map((n) => this.ctx.createPattern(n, 'repeat'));
  }

  render(on, instant) {
    this.target = on ? 1 : 0;
    if (instant) { this.pos = this.target; this.scene = 0; }
  }

  tick(t, dt) {
    if (!this.scene && this.pos !== this.target) {
      this.scene = this.target ? 1 : 2; this.s = 0;
      this.slateN.textContent = this.scene === 1 ? 'SCENE 1' : 'SCENE 2';
      this.slateT.textContent = this.scene === 1 ? 'THE IDOL' : 'THE SEQUEL';
    }
    if (this.scene) {
      const end = this.scene === 1 ? 1 : 0;
      this.s += (dt / 1000) * (end !== this.target ? 3.5 : 1);
      if (this.s >= (this.scene === 1 ? D1 : D2)) { this.pos = end; this.scene = 0; this.since = 0; }
    } else this.since += dt / 1000;
    this.slate.style.opacity = this.scene ? clamp(this.s / 0.2) : 1 - clamp((this.since - 0.9) / 0.35);
    if (this.ctx) this.draw(t);
  }

  draw(t) {
    const ctx = this.ctx, k = this.k;
    const scene = this.scene || (this.pos ? 1 : 2);
    const s = this.scene ? this.s : (this.pos ? D1 : D2);
    const w = world(scene, s, t);

    ctx.setTransform(k, 0, 0, k, 0, 0);
    ctx.globalCompositeOperation = 'source-over'; ctx.globalAlpha = 1;
    ctx.save();
    const sh = w.shake;
    ctx.translate(sh * Math.sin(s * 93) + 0.25 * Math.sin(t * 0.011), sh * Math.cos(s * 71) + 0.35 * Math.sin(t * 0.0073));
    ctx.drawImage(this.wall, -4, -4, TW + 8, TH + 8);

    // torch flames + embers
    TORCHES.forEach((tc, i) => {
      const f = flicker(t, i);
      ctx.save(); ctx.translate(tc.x, tc.y + 3);
      ctx.scale(0.9 + 0.15 * f, 0.8 + 0.35 * f);
      const fl = (r, h, c) => { ctx.fillStyle = c; ctx.beginPath(); ctx.moveTo(-r, 0); ctx.quadraticCurveTo(-r, -h * 0.5, 0.4 * Math.sin(t * 0.02 + i), -h); ctx.quadraticCurveTo(r, -h * 0.5, r, 0); ctx.closePath(); ctx.fill(); };
      fl(3.4, 11, 'rgba(255,110,30,.9)'); fl(2.2, 8, 'rgba(255,190,70,.95)'); fl(1.1, 4.5, 'rgba(255,245,200,1)');
      ctx.restore();
      for (let j = 0; j < 4; j++) {
        const age = ((t / 1000) * 0.9 + hash(j + i * 10)) % 1.1;
        ctx.fillStyle = `rgba(255,170,80,${0.8 * (1 - age / 1.1)})`;
        ctx.fillRect(tc.x + Math.sin(age * 6 + j) * 3, tc.y - 6 - age * 26, 0.9, 0.9);
      }
    });

    // dust motes in the torchlight
    for (let i = 0; i < 22; i++) {
      const x = (hash(i) * TW + t * 0.004 * (0.5 + hash(i + 9))) % TW;
      const y = 10 + hash(i + 3) * (G - 20) + Math.sin(t * 0.0008 + i) * 4;
      ctx.fillStyle = `rgba(255,215,160,${0.18 + 0.15 * Math.sin(t * 0.002 + i)})`;
      ctx.fillRect(x, y, 0.7, 0.7);
    }

    if (w.idolNiche) {
      const gl = scene === 2 ? Math.max(0, 1 - Math.abs(s - 2.56) / 0.12) : 0;
      drawIdol(ctx, NX, NY, gl, EX);
    }

    // ceiling dust when the trap springs
    if (scene === 1 && s > 0.44) {
      for (let i = 0; i < 18; i++) {
        const age = s - (0.44 + hash(i) * 0.35);
        if (age <= 0 || age > 0.9) continue;
        ctx.fillStyle = `rgba(200,165,120,${0.8 * (1 - age / 0.9)})`;
        const r = 0.6 + hash(i + 3) * 0.9;
        ctx.fillRect(14 + hash(i + 5) * (TW - 28), 5 + 0.5 * 260 * age * age, r, r);
      }
    }

    // rolling dust trail
    const trail = (from, to, bxAt, side) => {
      for (let j = 0; j < 40; j++) {
        const tj = from + j * 0.045; if (tj > to || tj > s) break;
        const age = s - tj; if (age > 0.6) continue;
        const ox = bxAt(tj) + side * BR * 0.55, a = 0.24 * (1 - age / 0.6);
        ctx.fillStyle = `rgba(190,150,110,${a})`;
        ctx.beginPath(); ctx.arc(ox + side * (20 + hash(j) * 20) * age, G - 2 - (15 + hash(j + 1) * 15) * age, 1.5 + age * 6, 0, TAU); ctx.fill();
      }
    };
    if (scene === 1) trail(0.55, 1.88, (x) => boulder1(x)[0], -1);
    else trail(0.45, 1.6, (x) => boulder2(x)[0], 1);

    drawBoulder(ctx, w.bx, w.by, w.rot);
    if (w.hat) drawHat(ctx, w.hat.x, w.hat.y, w.hat.rot, w.hat.squash || 0, EX);

    // thud puff
    if (scene === 1 && s > 1.88) {
      for (let i = 0; i < 24; i++) {
        const age = s - 1.88; if (age > 0.9) break;
        const ang = Math.PI + 0.15 + hash(i) * (Math.PI - 0.3), sp = 40 + hash(i + 2) * 80;
        const d = (1 - Math.exp(-4 * age)) / 4;
        const ox = RX + (hash(i + 4) - 0.5) * 80;
        ctx.fillStyle = `rgba(200,160,115,${0.42 * (1 - age / 0.9)})`;
        ctx.beginPath(); ctx.arc(ox + Math.cos(ang) * sp * d, G - 3 + Math.sin(ang) * sp * d * 0.7, 2 + age * 10, 0, TAU); ctx.fill();
      }
    }

    if (w.exp) {
      drawExplorer(ctx, w.exp);
      if (w.exp.mark) {  // "!"
        const [hx, hy] = headPos(w.exp);
        const pop = ease.outBack(seg(s, 0.58, 0.66), 2.2);
        ctx.save(); ctx.translate(hx, hy - 13 * KS); ctx.scale(pop * KS, pop * KS);
        ctx.fillStyle = '#ffe6a8'; ctx.font = '900 11px system-ui, sans-serif'; ctx.textAlign = 'center'; ctx.fillText('!', 0, 0);
        ctx.restore();
      }
    }

    // sweat drops while pushing
    if (scene === 2) {
      for (let j = 0; j < 4; j++) {
        const tj = 0.55 + j * 0.27, age = s - tj;
        if (age <= 0 || age > 0.5) continue;
        const [hx, hy] = headPos(exp2(tj, t, boulder2(tj)[0]));
        const x = hx + 4 * KS + 32 * age, y = hy - 3 * KS - 45 * age + 0.5 * 330 * age * age;
        ctx.fillStyle = `rgba(190,228,255,${1 - age / 0.5})`;
        ctx.beginPath(); ctx.moveTo(x, y - 2.2); ctx.quadraticCurveTo(x + 1.4, y, x, y + 1); ctx.quadraticCurveTo(x - 1.4, y, x, y - 2.2); ctx.fill();
      }
      // hand-dusting puffs
      for (const [t0, n] of [[2.64, 0], [2.72, 1]]) {
        const age = s - t0; if (age <= 0 || age > 0.4) continue;
        for (let i = 0; i < 6; i++) {
          const ang = -Math.PI / 2 + (hash(i + n * 7) - 0.5) * 2.2;
          ctx.fillStyle = `rgba(210,180,140,${0.5 * (1 - age / 0.4)})`;
          ctx.beginPath(); ctx.arc(NX + 7 * KS + Math.cos(ang) * 18 * age, G - 25 + Math.sin(ang) * 18 * age, 0.8 + age * 3, 0, TAU); ctx.fill();
        }
      }
    }
    ctx.restore();

    // torchlight
    ctx.globalCompositeOperation = 'screen';
    TORCHES.forEach((tc, i) => {
      const f = flicker(t, i);
      const g = ctx.createRadialGradient(tc.x, tc.y, 2, tc.x, tc.y + 20, 120);
      g.addColorStop(0, `rgba(255,160,70,${0.42 * f})`); g.addColorStop(0.35, `rgba(255,120,40,${0.14 * f})`); g.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = g; ctx.fillRect(0, 0, TW, TH);
    });
    ctx.globalCompositeOperation = 'source-over';

    // projector flicker + vignette
    ctx.fillStyle = `rgba(0,0,0,${0.03 + 0.05 * hash(Math.floor(t / 42))})`; ctx.fillRect(0, 0, TW, TH);
    const vg = ctx.createRadialGradient(TW / 2, TH / 2, 30, TW / 2, TH / 2, TW * 0.6);
    vg.addColorStop(0, 'rgba(0,0,0,0)'); vg.addColorStop(1, 'rgba(0,0,0,.6)');
    ctx.fillStyle = vg; ctx.fillRect(0, 0, TW, TH);

    // film grain (device pixels)
    const fr = Math.floor(t / 42);
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalCompositeOperation = 'overlay'; ctx.globalAlpha = 0.09;
    const ox = hash(fr) * 128, oy = hash(fr + 1) * 128;
    ctx.translate(-ox, -oy); ctx.fillStyle = this.pats[fr % 4];
    ctx.fillRect(0, 0, this.cv.width + 128, this.cv.height + 128);
    ctx.setTransform(k, 0, 0, k, 0, 0);
    ctx.globalCompositeOperation = 'source-over'; ctx.globalAlpha = 1;

  }
}

customElements.define('tg-boulder', Boulder);

