    g.restore();
    let bz = g.createLinearGradient(0, WY - BZ, 0, WY + TH + BZ);
    bz.addColorStop(0, '#4a5163'); bz.addColorStop(0.12, '#262b37'); bz.addColorStop(0.5, '#171a22'); bz.addColorStop(0.88, '#1f232d'); bz.addColorStop(1, '#3a4152');
    this.pill(g, WX - BZ, WY - BZ, TW + BZ * 2, TH + BZ * 2); g.fillStyle = bz; g.fill();
    this.pill(g, WX - BZ + 0.75, WY - BZ + 0.75, TW + BZ * 2 - 1.5, TH + BZ * 2 - 1.5);
    g.strokeStyle = `rgba(150,185,255,${0.22 + 0.12 * dk})`; g.lineWidth = 1.2; g.stroke();
    // Brushed sheen.
    bz = g.createLinearGradient(WX - BZ, 0, WX + TW + BZ, 0);
    bz.addColorStop(0, 'rgba(255,255,255,0)'); bz.addColorStop(0.3, 'rgba(255,255,255,.05)'); bz.addColorStop(0.5, 'rgba(255,255,255,0)'); bz.addColorStop(0.75, 'rgba(255,255,255,.04)'); bz.addColorStop(1, 'rgba(255,255,255,0)');
    this.pill(g, WX - BZ, WY - BZ, TW + BZ * 2, TH + BZ * 2); g.fillStyle = bz; g.fill();
    // Sunlight catching the bezel near the sun.
    if (vis > 0.01) {
      g.save(); g.globalCompositeOperation = 'lighter';
      const sg = g.createRadialGradient(SX, CY, RS, SX, CY, RS + 50);
      sg.addColorStop(0, `rgba(255,190,110,${0.22 * Math.pow(vis, 0.6)})`); sg.addColorStop(1, 'rgba(255,160,80,0)');
      this.pill(g, WX - BZ, WY - BZ, TW + BZ * 2, TH + BZ * 2); g.fillStyle = sg; g.fill();
      g.restore();
    }

    // ── Everything below lives inside the window.
    g.save();
    this.pill(g, WX, WY, TW, TH); g.clip();

    // Sky.
    const dayTop = [12, 38, 92], dayBot = [4, 14, 44], nightTop = [3, 4, 12], nightBot = [1, 1, 5];
    const sky = g.createRadialGradient(SX, CY, 10, SX, CY, TW);
    sky.addColorStop(0, rgb(mixC([40, 86, 168], [10, 12, 26], dk)));
    sky.addColorStop(0.45, rgb(mixC(dayTop, nightTop, dk)));
    sky.addColorStop(1, rgb(mixC(dayBot, nightBot, dk)));
    g.fillStyle = sky; g.fillRect(WX, WY, TW, TH);

    // Stars (faint by day, full at totality).
    for (const st of this.stars) {
      const tw = 0.6 + 0.4 * Math.sin(s * st.sp + st.ph);
      const a = (0.12 + 0.88 * dk) * tw * (0.35 + st.r * 0.6);
      g.fillStyle = `rgba(220,230,255,${a})`;
      g.beginPath(); g.arc(WX + st.x * TW, WY + st.y * TH, st.r * 0.9, 0, 6.283); g.fill();
    }

    // Deep partial eclipse: a 360° sunset glows on the horizon under a violet zenith.
    if (pf > 0.01) {
      const tg = g.createLinearGradient(0, WY, 0, WY + TH);
      tg.addColorStop(0, `rgba(78,44,130,${0.38 * pf})`);
      tg.addColorStop(0.5, `rgba(40,28,72,${0.12 * pf})`);
      tg.addColorStop(0.78, `rgba(255,112,70,${0.3 * pf})`);
      tg.addColorStop(1, `rgba(255,176,96,${0.6 * pf})`);
      g.fillStyle = tg; g.fillRect(WX, WY, TW, TH);
    }

    // Shadow bands: faint ripples racing across the ground just before totality.
    if (sb > 0.01) {
      g.save(); g.translate(CX, CY); g.rotate(-0.32);
      const off = (s * 30) % 9;
      for (let k = -30; k <= 30; k++) {
        const x = k * 9 + off, a = sb * (0.5 + 0.5 * Math.sin(k * 1.9 + s * 4));
        g.fillStyle = `rgba(255,236,210,${0.1 * a})`; g.fillRect(x, -160, 3, 320);
        g.fillStyle = `rgba(0,0,12,${0.16 * a})`; g.fillRect(x + 4.5, -160, 3, 320);
      }
      g.restore();
    }

    g.globalCompositeOperation = 'lighter';
    // Sunlight halo — scales with visible fraction.
    const glow = Math.pow(vis, 0.6);
    if (glow > 0.001) {
      const hR = 80 + 170 * glow;
      const halo = g.createRadialGradient(SX, CY, RS * 0.6, SX, CY, hR);
      halo.addColorStop(0, `rgba(255,214,140,${0.75 * glow})`);
      halo.addColorStop(0.3, `rgba(255,150,60,${0.28 * glow})`);
      halo.addColorStop(1, 'rgba(255,120,40,0)');
      g.fillStyle = halo; g.beginPath(); g.arc(SX, CY, hR, 0, 6.283); g.fill();
      // Slow rotating flare spokes.
      g.save(); g.translate(SX, CY); g.rotate(s * 0.08);
      for (let i = 0; i < 18; i++) {
        const a = (i / 18) * 6.283, L = RS + (30 + 40 * h1(i)) * glow * (0.8 + 0.2 * Math.sin(s * 1.3 + i));
        const lg = g.createLinearGradient(0, 0, Math.cos(a) * L, Math.sin(a) * L);
        lg.addColorStop(0, `rgba(255,220,160,${0.22 * glow})`); lg.addColorStop(1, 'rgba(255,180,90,0)');
        g.strokeStyle = lg; g.lineWidth = 3 + 3 * h1(i * 3);
        g.beginPath(); g.moveTo(0, 0); g.lineTo(Math.cos(a) * L, Math.sin(a) * L); g.stroke();
      }
      g.restore();
    }

    // Corona — soft pearly glow + long streamers, grows into totality.
    const cor = smooth(0.0, 1, dk) * 0.35 + tot * 0.65;
    if (cor > 0.01) {
      const cg = g.createRadialGradient(SX, CY, RS, SX, CY, RS * 1.45);
      cg.addColorStop(0, `rgba(240,245,255,${0.85 * cor})`);
      cg.addColorStop(0.35, `rgba(200,218,255,${0.35 * cor})`);
      cg.addColorStop(1, 'rgba(160,180,255,0)');
      g.fillStyle = cg; g.beginPath(); g.arc(SX, CY, RS * 1.45, 0, 6.283); g.fill();
      // Pearly light filling the whole window evenly (so no side looks cut off).
      g.fillStyle = `rgba(170,190,255,${0.07 * cor})`; g.fillRect(WX, WY, TW, TH);
      g.save(); g.translate(SX, CY); g.rotate(s * 0.03);
      for (const r of this.rays) {
        // Streamers bunch toward the "equator" like a real solar-minimum corona.
        const eq = 0.45 + 0.55 * Math.abs(Math.cos(r.a));
        const L = RS * (1.08 + (0.1 + 0.32 * r.len * r.len) * eq * (0.85 + 0.15 * Math.sin(s * 0.9 + r.ph))) * (0.75 + 0.25 * cor);
        const x1 = Math.cos(r.a) * RS * 0.96, y1 = Math.sin(r.a) * RS * 0.96;
        const x2 = Math.cos(r.a + 0.04 * Math.sin(r.ph)) * L, y2 = Math.sin(r.a + 0.04 * Math.sin(r.ph)) * L;
        const lg = g.createLinearGradient(x1, y1, x2, y2);
        lg.addColorStop(0, `rgba(240,245,255,${0.33 * cor})`); lg.addColorStop(1, 'rgba(200,215,255,0)');
        g.strokeStyle = lg; g.lineWidth = r.w * 1.4;
        g.beginPath(); g.moveTo(x1, y1); g.lineTo(x2, y2); g.stroke();
      }
      g.restore();
    }
    g.globalCompositeOperation = 'source-over';

    // Sun disc with limb darkening and slow granulation.
    const sd = g.createRadialGradient(SX - 4 * K, CY - 5 * K, 2 * K, SX, CY, RS);
    sd.addColorStop(0, '#fffdf2'); sd.addColorStop(0.55, '#ffe9a8'); sd.addColorStop(0.85, '#ffb04a'); sd.addColorStop(1, '#ff7a1c');
    g.fillStyle = sd; g.beginPath(); g.arc(SX, CY, RS, 0, 6.283); g.fill();
    g.save(); g.beginPath(); g.arc(SX, CY, RS, 0, 6.283); g.clip();
    g.globalCompositeOperation = 'soft-light';
    for (let i = 0; i < 24; i++) {
      const a = h1(i * 2.7) * 6.283 + s * 0.05 * (i % 2 ? 1 : -1), rr = Math.sqrt(h1(i * 5.1)) * RS * 0.9;
      g.fillStyle = `rgba(${i % 3 ? 255 : 160},${i % 3 ? 240 : 90},${i % 3 ? 200 : 30},0.35)`;
      g.beginPath(); g.arc(SX + Math.cos(a) * rr, CY + Math.sin(a) * rr, (3 + 4 * h1(i * 9.3)) * K, 0, 6.283); g.fill();
    }
    g.restore();

    // Prominences — tiny pink arcs at the limb, only visible near totality.
    if (tot > 0.01) {
      g.save(); g.globalCompositeOperation = 'lighter';
      for (const [a, sz] of [[-2.3, 1], [0.6, 0.7], [2.6, 0.55]]) {
        const px = SX + Math.cos(a) * RM, py = CY + Math.sin(a) * RM;
        const pg = g.createRadialGradient(px, py, 0, px, py, 5 * sz * K);
        pg.addColorStop(0, `rgba(255,90,120,${0.9 * tot})`); pg.addColorStop(1, 'rgba(255,60,100,0)');
        g.fillStyle = pg; g.beginPath(); g.arc(px, py, 5 * sz * K, 0, 6.283); g.fill();
      }
      g.restore();
    }

    // Moon — grey with an earthshine rim at rest, pure black against the sun.
    const lit = 1 - smooth(0.0, 0.5, 1 - vis);
    const md = g.createRadialGradient(mx - 9 * K, my - 10 * K, 2 * K, mx, my, RM);
    md.addColorStop(0, rgb(mixC([4, 5, 9], [86, 92, 112], lit)));
    md.addColorStop(0.7, rgb(mixC([2, 2, 5], [44, 48, 64], lit)));
    md.addColorStop(1, rgb(mixC([0, 0, 2], [22, 24, 36], lit)));
    g.fillStyle = md; g.beginPath(); g.arc(mx, my, RM, 0, 6.283); g.fill();
    if (lit > 0.02) {
      // Craters.
      g.save(); g.beginPath(); g.arc(mx, my, RM, 0, 6.283); g.clip();
      for (const [cx, cy, cr] of [[-10, -8, 6], [8, 6, 8], [12, -12, 3.5], [-6, 13, 4], [-16, 4, 3]]) {
        g.fillStyle = `rgba(10,12,22,${0.35 * lit})`; g.beginPath(); g.arc(mx + cx * K, my + cy * K, cr * K, 0, 6.283); g.fill();
        g.strokeStyle = `rgba(150,160,190,${0.18 * lit})`; g.lineWidth = 1; g.beginPath(); g.arc(mx + (cx - 0.6) * K, my + (cy - 0.6) * K, cr * K, 3.6, 5.6); g.stroke();
      }
      g.restore();
      g.strokeStyle = `rgba(170,190,255,${0.35 * lit})`; g.lineWidth = 1.4;
      g.beginPath(); g.arc(mx, my, RM - 0.5, 2.6, 5.4); g.stroke();
    }

    // Diamond ring + Baily's beads at the last sliver (left limb, opposite the moon's approach).
    if (vis < 0.14 && (vis > 0 || ring > 0.01)) {
      g.save(); g.globalCompositeOperation = 'lighter';
      const ang = Math.atan2(CY - my, SX - mx);   // last sliver: the limb facing away from the moon
      const bx = SX + Math.cos(ang) * RS, by = CY + Math.sin(ang) * RS;
      const beads = smooth(0.14, 0.02, vis) * smooth(0, 0.004, vis);
      for (let i = -3; i <= 3; i++) {
        if (i === 0) continue;
        const a = ang + i * 0.16 * (1 + vis * 6), fl = 0.6 + 0.4 * Math.sin(this.q * 400 + i * 2.1);
        const px = SX + Math.cos(a) * (RS + 0.3), py = CY + Math.sin(a) * (RS + 0.3);
        const bg = g.createRadialGradient(px, py, 0, px, py, 4.6);
        bg.addColorStop(0, `rgba(255,255,255,${beads * fl * (1 - Math.abs(i) * 0.18)})`); bg.addColorStop(1, 'rgba(255,240,220,0)');
        g.fillStyle = bg; g.beginPath(); g.arc(px, py, 4.6, 0, 6.283); g.fill();
      }
      if (ring > 0.01) {
        const R = 8 + 46 * ring;
        const dg = g.createRadialGradient(bx, by, 0, bx, by, R);
        dg.addColorStop(0, `rgba(255,255,255,${ring})`); dg.addColorStop(0.2, `rgba(255,250,235,${0.7 * ring})`); dg.addColorStop(1, 'rgba(255,230,200,0)');
        g.fillStyle = dg; g.beginPath(); g.arc(bx, by, R, 0, 6.283); g.fill();
        // Cross spikes.
        for (const [dx, dy, L] of [[1, 0, 110], [0, 1, 64], [0.7, 0.7, 34], [0.7, -0.7, 34]]) {
          for (const sgn of [1, -1]) {
            const lg = g.createLinearGradient(bx, by, bx + dx * L * sgn * ring, by + dy * L * sgn * ring);
            lg.addColorStop(0, `rgba(255,255,255,${0.9 * ring})`); lg.addColorStop(1, 'rgba(255,255,255,0)');
            g.strokeStyle = lg; g.lineWidth = 1.3;
            g.beginPath(); g.moveTo(bx, by); g.lineTo(bx + dx * L * sgn * ring, by + dy * L * sgn * ring); g.stroke();
          }
        }
        // Whole-scene flash.
        g.fillStyle = `rgba(255,250,240,${0.12 * ring * ring})`; g.fillRect(WX, WY, TW, TH);
      }
      g.restore();
    }

    // Snow Globe lip: recessed inner shadow + faint lower highlight.
    let lp = g.createLinearGradient(0, WY, 0, WY + 16);
    lp.addColorStop(0, 'rgba(0,0,0,.5)'); lp.addColorStop(1, 'rgba(0,0,0,0)');
    g.fillStyle = lp; g.fillRect(WX, WY, TW, 16);
    g.restore();                          // end window clip
    // Corona light spilling over the bezel all round, so the halo reads whole at the pill's end.
    if (tot > 0.01) {
      g.save(); g.globalCompositeOperation = 'lighter';
      const OR = RS + 66, og = g.createRadialGradient(SX, CY, 0, SX, CY, OR);
      og.addColorStop(0, 'rgba(160,180,255,0)'); og.addColorStop((RS + 2) / OR, 'rgba(160,180,255,0)');
      og.addColorStop((RS + 10) / OR, `rgba(215,228,255,${0.3 * tot})`); og.addColorStop(1, 'rgba(160,180,255,0)');
      g.fillStyle = og; g.fillRect(SX - 130, CY - 130, 260, 260);
      g.restore();
    }
    this.pill(g, WX + 0.75, WY + 0.75, TW - 1.5, TH - 1.5); g.strokeStyle = 'rgba(0,0,0,.45)'; g.lineWidth = 1.5; g.stroke();
    this.pill(g, WX + 1.5, WY + 1.5, TW - 3, TH - 3);
    lp = g.createLinearGradient(0, WY, 0, WY + TH);
    lp.addColorStop(0, 'rgba(255,255,255,0)'); lp.addColorStop(0.85, 'rgba(255,255,255,0)'); lp.addColorStop(1, 'rgba(200,220,255,.18)');
    g.strokeStyle = lp; g.lineWidth = 1.2; g.stroke();
    g.restore();
  }

  pill(g, x, y, w, h) {
    const r = h / 2;
    g.beginPath();
    g.moveTo(x + r, y); g.lineTo(x + w - r, y); g.arc(x + w - r, y + r, r, -Math.PI / 2, Math.PI / 2);
    g.lineTo(x + r, y + h); g.arc(x + r, y + r, r, Math.PI / 2, Math.PI * 1.5); g.closePath();
  }
}

