const tri = (d, u, n, x) => (x < 0.5 ? mix(d, u, x * 2) : mix(u, n, (x - 0.5) * 2));
const grad = (stops, f) => {
  const s = stops.length - 1, i = Math.min(s - 1, Math.floor(f * s));
  return mix(stops[i], stops[i + 1], f * s - i);
};

// [day, dusk, night]
const PAL = Object.fromEntries(Object.entries({
  grass: ['#8cc66a', '#a39050', '#18264c'], grass2: ['#74b050', '#857a40', '#0f1a3a'],
  tuft: ['#5c9a3e', '#6a5a30', '#24346a'], mtn: ['#a8b3dc', '#8a6898', '#1c265a'],
  mtnHi: ['#c4cceb', '#b08aa8', '#5464aa'], path: ['#e0cc98', '#cf9e6c', '#2b3264'],
  wall: ['#f5f2ea', '#efc6a2', '#46528a'], wallLine: ['#dcd8ce', '#d6a888', '#313a66'],
  roof: ['#3f66bc', '#4a4890', '#2c3878'], roofLine: ['#30519c', '#3a3878', '#1c2658'],
  chim: ['#b8664a', '#a85240', '#3a2a44'], frame: ['#2f57ab', '#3a3f86', '#222b56'],
  glass: ['#d7edf9', '#ffd0a0', '#2a3466'], door: ['#2b3f7c', '#2a2f66', '#151b3c'],
  fence: ['#cc9c60', '#b8784a', '#3d3f66'], fenceHi: ['#e2b67a', '#d09060', '#4a4c74'],
  bench: ['#8c5c34', '#7a4a2a', '#282a46'], hair: ['#2a2030', '#2a2030', '#14142a'],
  skin: ['#f2c9a2', '#e8a882', '#5c5e88'], shirt: ['#ffffff', '#ffd9bc', '#7c84ae'],
  pants: ['#3256a8', '#3a3a80', '#1c2352'], trunk: ['#7a5232', '#6a4028', '#141a36'],
  trunkLo: ['#5c3c24', '#4e2e1e', '#0c1028'], leaf: ['#4f8c3a', '#5c6a30', '#0a1030'],
  leafHi: ['#78b24e', '#8c8a40', '#4a66c0'], leafLo: ['#3a6a2c', '#3a4628', '#080d2e'],
  cloud: ['#ffffff', '#ffb9a4', '#3a4270'], stone: ['#b8b4aa', '#a89080', '#3a3e60'],
  sun: ['#fff4b8', '#ff9548', '#ff5a3a'],
}).map(([k, v]) => [k, v.map(H)]));

const SKY_DAY = ['#7fbfe8', '#a8d6f2', '#c8e8f8'].map(H);
const SKY_GOLD = ['#4a3a7a', '#a8558a', '#e8706a', '#ff9f5a', '#ffd27e'].map(H);
const SKY_DAWN = ['#3e4886', '#9a78b4', '#ee9fb2', '#ffbfa8', '#ffe2c4'].map(H);
const SILH = H('#2b1b2e');
const BIRDS = [{ dx: 0, y: 13, ph: 0 }, { dx: 8, y: 17, ph: 1.7 }, { dx: 15, y: 11, ph: 3.1 }];
const SKY_NIGHT = ['#0a0f2e', '#1f2b68', '#3b4b94'].map(H);

// deterministic sprinkles
function rng(seed) {
  return () => { seed |= 0; seed = (seed + 0x6d2b79f5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
