}
const r = rng(7);
const STARS = Array.from({ length: 30 }, () => ({ x: (r() * SW) | 0, y: 1 + ((r() * 25) | 0), ph: r() * 6.28, sp: 0.6 + r() * 1.2, warm: r() < 0.3 }))
  .filter((s) => Math.hypot(s.x - 18, s.y - 8) > 7 && !(s.x > 90 && s.x < 111 && s.y > 11));
const SPARKLES = [{ x: 44, y: 6 }, { x: 72, y: 11 }, { x: 116, y: 4 }];
const TUFTS = Array.from({ length: 34 }, () => ({ x: (r() * SW) | 0, y: 41 + ((r() * 11) | 0) }));
const DANDS = Array.from({ length: 12 }, () => ({ x: 62 + ((r() * 56) | 0), y: 45 + ((r() * 6) | 0), puff: r() < 0.3 }));
const FLIES = Array.from({ length: 7 }, (_, i) => ({ x: 60 + r() * 56, y: 30 + r() * 16, i }));
const hM = (x) => Math.round(29 + 2.5 * Math.sin(x * 0.08 + 0.5) + 1.5 * Math.sin(x * 0.21));
const hH = (x) => Math.round(36 + 1.4 * Math.sin(x * 0.11 + 2) + 0.8 * Math.sin(x * 0.3));

export default class SnowGlobe extends ToggleBase {
  template() {
    return `
<style>
  .sg { position: absolute; left: 15px; top: 30px; width: 330px; height: 160px; border-radius: 80px; }
  .glow { position: absolute; left: 34px; right: 34px; bottom: -30px; height: 70px; border-radius: 50%;
    background: radial-gradient(closest-side, rgba(255,168,64,.62), rgba(255,140,40,0)); filter: blur(10px);
    opacity: var(--glow, 0); transition: opacity .45s ease; }
  .bezel { position: absolute; inset: 0; border-radius: 80px; background: var(--bz, #EAE7DF);
    box-shadow: 0 26px 44px -20px rgba(30,24,16,var(--sh,.45)), 0 8px 16px -8px rgba(30,24,16,var(--sh,.3)),
      inset 0 2px 1px rgba(255,255,255,var(--hl,.9)), inset 0 -4px 8px rgba(0,0,0,.14); }
  .rim { position: absolute; inset: 0; border-radius: 80px; pointer-events: none;
    box-shadow: inset 0 -3px 3px -1px rgba(255,186,96,var(--rim,0)); transition: box-shadow .45s ease; }
  .win { position: absolute; left: 15px; top: 15px; width: ${WIN_W}px; height: ${WIN_H}px; border-radius: 65px; overflow: hidden; background: #000; }
  canvas { position: absolute; left: 0; top: 0; }
  .lip { position: absolute; inset: 0; border-radius: 65px; pointer-events: none;
    box-shadow: inset 0 6px 9px rgba(0,0,0,.38), inset 0 -2px 3px rgba(255,255,255,.16), inset 0 0 0 1.5px rgba(0,0,0,.28); }
</style>
<div class="sg" data-hit>
  <div class="glow"></div><div class="bezel"></div><div class="rim"></div>
  <div class="win"><canvas></canvas><div class="lip"></div></div>
</div>`;
  }

  setup() {
    this.cv = this.$('canvas');
    this.sc = document.createElement('canvas');
    this.sc.width = SW; this.sc.height = SH;
    this.g = this.sc.getContext('2d');
    this.sg = this.$('.sg');
    this.p = this.checked ? 1 : 0;
    this._dir = this.checked ? 1 : -1;
    this.dw = this.checked ? 0 : 1;   // 0 = golden-hour palette (going to night), 1 = dawn palette
