    const lit = n > 0.8;
    const warm = mix(H('#E7C29C'), H('#E6C2C6'), dw), warmHi = mix(H('#F6DDBE'), H('#F5DCDD'), dw);
    let bg = mix(H('#F5F3EC'), H('#1B1D28'), n), bgHi = mix(H('#FCFBF7'), H('#272A3B'), n);
