  drawScene(n, t, mid = 0, dw = 0) {
    const g = this.g;
    const P = (x, y, w, h, c) => { g.fillStyle = c; g.fillRect(x, y, w, h); };
    const k = {};
    for (const key in PAL) k[key] = rgb(tri(...PAL[key], n));
