    const rows = [];
    for (let y = 0; y < 40; y++) {
      const f = Math.min(1, Math.floor(y / 4) / 9);
      rows[y] = rgb(tri(grad(SKY_DAY, f), mix(grad(SKY_GOLD, f), grad(SKY_DAWN, f), dw), grad(SKY_NIGHT, f), n));
