              box-shadow: 0 14px 24px -8px rgba(50,54,80,.34), 0 3px 6px -2px rgba(50,54,80,.2), inset 0 1px 0 #fff, inset 0 -3px 4px rgba(0,0,0,.05); }
            .rn { box-shadow: inset 1.5px -2px 0 0 rgba(228,234,255,.96), inset 2px -8px 10px -6px rgba(140,160,255,.95),
                -2px 7px 20px -4px rgba(120,145,255,.95), -1px 2px 5px -1px rgba(190,205,255,.9); }
            .rd { box-shadow: inset -1.5px 2px 0 0 rgba(255,246,222,.96), inset -2px 8px 10px -6px rgba(255,168,58,.92),
                2px -7px 20px -4px rgba(255,158,48,.75), 1px -2px 5px -1px rgba(255,200,120,.85); }
            .bzm { position: absolute; inset: 0; border-radius: 80px; opacity: 0;
              background: linear-gradient(180deg, #5e566f, #463f56 55%, #362f45);
              box-shadow: inset 0 2px 1px rgba(255,230,240,.35), inset 0 -4px 8px rgba(20,10,40,.4), inset 0 0 0 1px rgba(255,255,255,.05); }
            .tm { position: absolute; inset: 0; border-radius: inherit; opacity: 0;
              background: linear-gradient(180deg, #1d1828, #2f2740 70%, #3a2f4a);
              box-shadow: inset 0 7px 14px rgba(8,4,20,.75), inset 0 -1px 0 rgba(255,200,220,.12); }
            .km { opacity: 0; background: linear-gradient(155deg, #8c82a0 0%, #675e7c 45%, #463f58 100%);
              box-shadow: 0 13px 24px -7px rgba(20,10,40,.6), inset 0 1px 0 rgba(255,235,245,.4), inset 0 0 0 1px rgba(255,255,255,.08); }
            .km::after { content: ''; position: absolute; inset: 1px; border-radius: 50%;
              background: radial-gradient(120% 80% at 30% 10%, rgba(255,220,235,.22), rgba(255,255,255,0) 60%); }
            .rm { opacity: 0; box-shadow: inset 1.5px -2px 0 0 rgba(236,200,255,.9), inset 2px -8px 10px -6px rgba(176,120,255,.9),
                inset -1.5px 2px 0 0 rgba(255,214,190,.85), inset -2px 8px 10px -6px rgba(255,130,120,.75),
                -2px 7px 20px -4px rgba(170,110,255,.85), 2px -7px 20px -4px rgba(255,120,110,.6); }
            .bm { background: radial-gradient(closest-side, rgba(255,120,150,.55), rgba(170,100,255,0)); mix-blend-mode: screen; opacity: 0; }
            canvas { position: absolute; left: 0; top: 0; pointer-events: none; }
          </style>
          <div class="tg-stage">
            <div class="sg" data-hit><div class="bz"></div><div class="bzn"></div><div class="bzd"></div><div class="bzm"></div></div>
            <div class="trk" data-hit><div class="tn"></div><div class="td"></div><div class="tm"></div><div class="lip"></div></div>
            <div class="bl bn"></div><div class="bl bd"></div><div class="bl bm"></div>
            <div class="knob" data-hit><div class="kn"></div><div class="kd"></div><div class="km"></div><div class="rn"></div><div class="rd"></div><div class="rm"></div><canvas></canvas></div>
          </div>`;
        this.root.addEventListener("click", (e) => {
          if (e.composedPath().some((n) => n instanceof Element && n.hasAttribute("data-hit"))) this.toggle();
        });
        this._built = true;
        this.setup();
        this.p = this.checked ? 1 : 0;
      }
      this._ro = new ResizeObserver(() => this._fit());
      this._ro.observe(this);
      this._fit();
      const loop = (t) => {
        const dt = this._last ? Math.min(t - this._last, 64) : 16;
        this._last = t;
        this.tick(t, dt);
        this._raf = requestAnimationFrame(loop);
      };
      this._raf = requestAnimationFrame(loop);
    }

    disconnectedCallback() {
      cancelAnimationFrame(this._raf);
      this._ro?.disconnect();
      this._last = 0;
    }

    _fit() {
      const { W, H } = this.constructor;
      const r = this.getBoundingClientRect();
      if (!r.width || !r.height) return;
      this.scale = Math.min(r.width / W, r.height / H) * (parseFloat(this.getAttribute("fill")) || 0.92);
      this.style.setProperty("--s", this.scale);
      this.ctx = this.sizeCanvas(this.cv, K, K);
      this.ctx.lineJoin = "round";
    }

    get checked() { return this.hasAttribute("checked"); }
    set checked(v) { this.toggleAttribute("checked", !!v); }

    attributeChangedCallback(name, oldV, newV) {
      if (name === "checked" && this._built && (oldV === null) !== (newV === null)) {
        this.dispatchEvent(new CustomEvent("change", { detail: { checked: this.checked }, bubbles: true }));
      }
    }

    toggle() { this.checked = !this.checked; }

    sizeCanvas(cv, w, h) {
      const k = this.scale * this.dpr;
      cv.width = Math.max(1, Math.round(w * k));
      cv.height = Math.max(1, Math.round(h * k));
      cv.style.width = w + "px";
      cv.style.height = h + "px";
      const ctx = cv.getContext("2d");
      ctx.setTransform(k, 0, 0, k, 0, 0);
      return ctx;
    }

    setup() {
      const ang = (d) => Math.atan2(d.y - K / 2, d.x - K / 2);
      const sets = [moonDots(), horizonDots(), sunDots()].map((a) => a.sort((u, v) => ang(u) - ang(v)));
      const N = Math.max(...sets.map((a) => a.length));
      const seen = sets.map(() => new Set());
      this.parts = Array.from({ length: N }, (_, i) => {
        const pts = sets.map((set, k) => {
          const j = Math.floor((i * set.length) / N);
          const dup = seen[k].has(j);
          seen[k].add(j);
          return { ...set[j], dup };
        });
        const a = pts[0], dx = a.x - K / 2, dy = a.y - K / 2, len = Math.hypot(dx, dy) || 1;
        return {
          pts, bx: dx / len, by: dy / len, amp: 9 + ((i * 37) % 13),
          sw: 0.9 + ((i * 53) % 7) / 10, delay: (((i * 29) % 17) / 17) * 0.18,
        };
      });
      const q = (s) => this.root.querySelector(s);
      this.cv = q("canvas");
      this.knob = q(".knob");
      this.L = {
        bzn: q(".bzn"), bzd: q(".bzd"), bzm: q(".bzm"), lip: q(".lip"),
        tn: q(".tn"), td: q(".td"), tm: q(".tm"),
        kn: q(".kn"), kd: q(".kd"), km: q(".km"),
        rn: q(".rn"), rd: q(".rd"), rm: q(".rm"),
        bn: q(".bn"), bd: q(".bd"), bm: q(".bm"),
      };
      this._k = "";
    }

    posOf(p) {
      if (p < P1) return 0.47 * ease.inOutCubic(p / P1);
      if (p < P2) return 0.47 + 0.06 * ((p - P1) / (P2 - P1));
      return 0.53 + 0.47 * ease.inOutCubic((p - P2) / (1 - P2));
    }

    tick(t, dt) {
      const target = this.checked ? 1 : 0;
      if (this.p !== target) {
        this.p = target > this.p ? Math.min(target, this.p + dt / DUR) : Math.max(target, this.p - dt / DUR);
      }
      const p = this.p;
      this.q1 = clamp((p - 0.03) / 0.3);
      this.q2 = clamp((p - 0.62) / 0.33);
      const kx = TX + KPAD + this.posOf(p) * TRAVEL;
      this.knob.style.transform = `translateX(${kx}px)`;
      this.L.bn.style.transform = `translate(${kx + K / 2 - 85 - 10}px, ${TY + KPAD + K - 30}px)`;
      this.L.bd.style.transform = `translate(${kx + K / 2 - 85 + 10}px, ${TY + KPAD - 34}px)`;
      this.L.bm.style.transform = `translate(${kx + K / 2 - 85}px, ${TY + KPAD + K / 2 - 32}px) scale(1.35, 1.6)`;

      const m = smooth(clamp((p - 0.3) / 0.4));
      const dusk = Math.pow(Math.sin(Math.PI * clamp((p - 0.06) / 0.88)), 1.4);
      const key = m.toFixed(3) + dusk.toFixed(3);
      if (key !== this._k) {
        this._k = key;
        const L = this.L, nd = 1 - dusk;
        L.bzn.style.opacity = L.tn.style.opacity = L.kn.style.opacity = (1 - m).toFixed(3);
        L.bzd.style.opacity = L.td.style.opacity = L.kd.style.opacity = m.toFixed(3);
        L.rn.style.opacity = L.bn.style.opacity = ((1 - m) * nd).toFixed(3);
        L.rd.style.opacity = L.bd.style.opacity = (m * nd).toFixed(3);
        L.bzm.style.opacity = L.tm.style.opacity = L.km.style.opacity = L.rm.style.opacity = dusk.toFixed(3);
        L.bm.style.opacity = (dusk * 0.9).toFixed(3);
        L.lip.style.setProperty("--lip", lerp(lerp(1, 0.45, m), 0.85, dusk).toFixed(3));
        let c0 = mix(H("#2a2a2f"), H("#fdfdfe"), m);
        let c1 = mix(H("#09090a"), H("#e3e5e9"), m);
        c0 = mix(c0, H("#6a5b78"), dusk * 0.92);
        c1 = mix(c1, H("#231c30"), dusk * 0.92);
        this.style.background = `radial-gradient(90% 90% at 50% 46%, ${rgb(c0)}, ${rgb(c1)})`;
      }
      if (this.ctx) this.draw(t);
    }

    draw(t) {
      const c = this.ctx;
      c.clearRect(0, 0, K, K);
      const C = K / 2;
      const night = [242, 245, 255], warm = [255, 214, 170], day = [30, 30, 36];
      const second = this.q2 > 0;
      const gq = second ? this.q2 : this.q1;

      for (const p of this.parts) {
        const A = second ? p.pts[1] : p.pts[0];
        const B = second ? p.pts[2] : p.pts[1];
        const q = clamp((gq - p.delay) / (1 - 0.18));
        const e = ease.inOutCubic(q);
        const loose = Math.sin(Math.PI * q);

        let rx = lerp(A.x, B.x, e) - C;
        let ry = lerp(A.y, B.y, e) - C;
        const th = p.sw * loose * (second ? -1.4 : 1.4);
        const cs = Math.cos(th), sn = Math.sin(th);
        [rx, ry] = [rx * cs - ry * sn, rx * sn + ry * cs];

        const burst = p.amp * Math.pow(loose, 0.6);
        const x = C + rx + p.bx * burst + Math.sin(t * 0.004 + p.amp) * loose * 1.5;
        const y = C + ry + p.by * burst + Math.cos(t * 0.0035 + p.sw * 9) * loose * 1.5;
        const ct = smooth(clamp((q - 0.35) / 0.3));
        const col = second ? mix(warm, day, ct) : mix(night, warm, ct);
        const s = lerp(A.s, B.s, e) * lerp(1, 0.6, loose);
        const va = A.dup ? 0 : 1, vb = B.dup ? 0 : 1;
        let alpha = lerp(va, vb, smooth(clamp((q - 0.25) / 0.6)));
        if (!second && q >= 1 && B.y > ORG + 10 * PITCH) alpha *= 0.55 + 0.45 * Math.sin(t * 0.006 + B.x * 0.35);
        if (!second && this.q1 < 0.02 && A.s < 0.7) alpha *= 0.75 + 0.25 * Math.sin(t * 0.003 + p.amp);
        if (alpha <= 0.01) continue;

        const size = 3.5 * s;
        const glowCol = second ? [255, 190, 140] : mix([200, 215, 255], [255, 170, 130], ct);
        const glow = second ? 1 - ct : 1;
        c.shadowColor = `rgba(${glowCol[0] | 0},${glowCol[1] | 0},${glowCol[2] | 0},${0.85 * glow})`;
        c.shadowBlur = 6 * glow * this.scale * this.dpr;

        if (second && ct > 0.5) {
          c.shadowBlur = 0;
          c.fillStyle = `rgba(255,255,255,${0.9 * alpha * (ct - 0.5) * 2})`;
          c.beginPath();
          c.roundRect(x - size / 2, y - size / 2 + 0.7, size, size, size * 0.3);
          c.fill();
        }

        c.fillStyle = rgb(col, alpha);
        c.beginPath();
        c.roundRect(x - size / 2, y - size / 2, size, size, size * lerp(0.28, 0.5, loose));
        c.fill();
      }
      c.shadowBlur = 0;
    }
  }

  customElements.define("tg-dotmatrix", DotMatrixElement);
}

export default function DotMatrixToggle() {
  const ref = useRef(null);
  const [checked, setChecked] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const onChange = (e) => setChecked(Boolean(e.detail?.checked));
    el.addEventListener("change", onChange);
    return () => el.removeEventListener("change", onChange);
  }, []);

  return (
    <div className="flex flex-col items-center gap-2">
      <tg-dotmatrix
        ref={ref}
        fill="0.96"
        aria-checked={checked}
        style={{
          display: "block",
          width: "220px",
          height: "135px",
          borderRadius: "28px",
          overflow: "hidden",
        }}
      />
    </div>
  );
}

