import React, { useEffect, useRef, useState } from "react";

const ease = {
  outCubic: (x) => 1 - Math.pow(1 - x, 3),
  inOutCubic: (x) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2),
  outBack: (x, s = 1.70158) => 1 + (s + 1) * Math.pow(x - 1, 3) + s * Math.pow(x - 1, 2),
  spring: (pos, vel, target, dt, k = 170, d = 18) => {
    const s = dt / 1000;
    const a = -k * (pos - target) - d * vel;
    vel += a * s;
    pos += vel * s;
    return [pos, vel];
  },
};

const clamp = (v, a = 0, b = 1) => Math.min(b, Math.max(a, v));
const lerp = (a, b, t) => a + (b - a) * t;

const BX = 15, BY = 30, BW = 330, BH = 160, BR = 80;
const TX = 30, TY = 45, TW = 300, TH = 130, R = 65;
const KY = BY + BH / 2;
const KR = 56;
const KX0 = TX + 9 + KR, KX1 = TX + TW - 9 - KR;
const EA = BX + BR - 1, EB = BX + BW - BR + 1;
const HH = 83;
const PAD = 60;
const CW = 360 + PAD * 2, CH = 220 + PAD * 2;
const ON_DUR = 1750, OFF_DUR = 1700;

function rng(seed) {
  let s = seed >>> 0;
  return () => ((s = (s * 1664525 + 1013904223) >>> 0) / 4294967296);
}

const VEINS = (() => {
  const r = rng(7);
  const out = [];
  for (let i = 0; i < 10; i++) {
    let x = TX + 40 + r() * (TW - 80), y = KY - 42 + r() * 84;
    let a = (r() < 0.5 ? 0 : Math.PI) + (r() - 0.5) * 0.9;
    const pts = [[x, y]];
    const n = 5 + Math.floor(r() * 4);
    for (let k = 0; k < n; k++) {
      a += (r() - 0.5) * 0.9;
      const ny = y + Math.sin(a) * 20;
      if (ny < KY - 55 || ny > KY + 55) a = -a;
      x += Math.cos(a) * 22;
      y += Math.sin(a) * 20;
      x = clamp(x, BX + 30, BX + BW - 30);
      pts.push([x, y]);
    }
    out.push({ pts, phase: r() * 6.28, w: 2.6 + r() * 2.2 });
  }
  return out;
})();

