<style>
  :host { background:
    radial-gradient(60% 55% at 50% 52%, #26272e 0%, #111216 55%, #060608 100%); }
  .floor { position: absolute; left: 20px; top: 150px; width: 320px; height: 90px; border-radius: 50%;
