.toggle-cont {
  --primary: #54a8fc;
  --light: #d9d9d9;
  --dark: #121212;
  --gray: #414344;

  position: relative;
  z-index: 10;

  width: fit-content;
  height: 50px;

  border-radius: 9999px;
}

.toggle-cont .toggle-input {
  display: none;
}

.toggle-cont .toggle-label {
  --gap: 5px;
  --width: 50px;

  cursor: pointer;

  position: relative;
  display: inline-block;

  padding: 0.5rem;
  width: calc((var(--width) + var(--gap)) * 2);
  height: 100%;
  background-color: var(--dark);

  border: 1px solid #777777;
  border-bottom: 0;

  border-radius: 9999px;
  box-sizing: content-box;
  transition: all 0.3s ease-in-out;
}
.toggle-label::before {
  content: "";

  position: absolute;
  z-index: -10;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);

  width: calc(100% + 1.5rem);
  height: calc(100% + 1.5rem);
  background-color: var(--gray);

  border: 1px solid #777777;
  border-bottom: 0;
  border-radius: 9999px;

  transition: all 0.3s ease-in-out;
}
.toggle-label::after {
  content: "";

  position: absolute;
  z-index: -10;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);

  width: 100%;
  height: 100%;
  background-image: radial-gradient(
    circle at 50% -100%,
    rgb(58, 155, 252) 0%,
    rgba(12, 12, 12, 1) 80%
  );

  border-radius: 9999px;
}

.toggle-cont .toggle-label .cont-icon {
  position: relative;

  display: flex;
  justify-content: center;
  align-items: center;

  position: relative;
  width: var(--width);
  height: 50px;
  background-image: radial-gradient(
    circle at 50% 0%,
    #666666 0%,
    var(--gray) 100%
  );

  border: 1px solid #aaaaaa;
  border-bottom: 0;
  border-radius: 9999px;
  box-shadow: inset 0 -0.15rem 0.15rem var(--primary),
    inset 0 0 0.5rem 0.75rem var(--second);

  transition: transform 0.3s ease-in-out;
}

.cont-icon {
  overflow: clip;
  position: relative;
}

.cont-icon .sparkle {
  position: absolute;
  top: 50%;
  left: 50%;

  display: block;

  width: calc(var(--width) * 1px);
  aspect-ratio: 1;
  background-color: var(--light);

  border-radius: 50%;
  transform-origin: 50% 50%;
  rotate: calc(1deg * var(--deg));
  transform: translate(-50%, -50%);
  animation: sparkle calc(100s / var(--duration)) linear
    calc(0s / var(--duration)) infinite;
}

@keyframes sparkle {
  to {
    width: calc(var(--width) * 0.5px);
    transform: translate(2000%, -50%);
  }
}

.cont-icon .icon {
  width: 1.1rem;
  fill: var(--light);
}

.toggle-cont:has(.toggle-input:checked) {
  --checked: true;
}

@container style(--checked: true) {
  .toggle-cont .toggle-label {
    background-color: #41434400;

    border: 1px solid #3d6970;
    border-bottom: 0;
  }

  .toggle-cont .toggle-label::before {
    box-shadow: 0 1rem 2.5rem -2rem #0080ff;
  }

  .toggle-cont .toggle-label .cont-icon {
    overflow: visible;

    background-image: radial-gradient(
      circle at 50% 0%,
      #045ab1 0%,
      var(--primary) 100%
    );

    border: 1px solid var(--primary);
    border-bottom: 0;

    transform: translateX(calc((var(--gap) * 2) + 100%)) rotate(-225deg);
  }

  .toggle-cont .toggle-label .cont-icon .sparkle {
    z-index: -10;

    width: calc(var(--width) * 1.5px);
    background-color: #acacac;

    animation: sparkle calc(100s / var(--duration)) linear
      calc(10s / var(--duration)) infinite;
  }

  @keyframes sparkle {
    to {
      width: calc(var(--width) * 1px);
      transform: translate(5000%, -50%);
    }
  }
}

.switch {
  font-size: 17px;
  position: relative;
  display: inline-block;
  width: 64px;
  height: 34px;
}

.switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

.slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: #73C0FC;
  transition: .4s;
  border-radius: 30px;
}

.slider:before {
  position: absolute;
  content: "";
  height: 30px;
  width: 30px;
  border-radius: 20px;
  left: 2px;
  bottom: 2px;
  z-index: 2;
  background-color: #e8e8e8;
  transition: .4s;
}

.sun svg {
  position: absolute;
  top: 6px;
  left: 36px;
  z-index: 1;
  width: 24px;
  height: 24px;
}

.moon svg {
  fill: #73C0FC;
  position: absolute;
  top: 5px;
  left: 5px;
  z-index: 1;
  width: 24px;
  height: 24px;
}

/* .switch:hover */.sun svg {
  animation: rotate 15s linear infinite;
}

@keyframes rotate {

  0% {
    transform: rotate(0);
  }

  100% {
    transform: rotate(360deg);
  }
}

/* .switch:hover */.moon svg {
  animation: tilt 5s linear infinite;
}

@keyframes tilt {

  0% {
    transform: rotate(0deg);
  }

  25% {
    transform: rotate(-10deg);
  }

  75% {
    transform: rotate(10deg);
  }

  100% {
    transform: rotate(0deg);
  }
}

.input:checked + .slider {
  background-color: #183153;
}

.input:focus + .slider {
  box-shadow: 0 0 1px #183153;
}

.input:checked + .slider:before {
  transform: translateX(30px);
}

#theme-toggle-button {
  font-size: 17px;
  position: relative;
  display: inline-block;
  width: 7em;
  cursor: pointer;
}

/* Hide default HTML checkbox */
#toggle {
  opacity: 0;
  width: 0;
  height: 0;
}

#container,
#patches,
#stars,
#button,
#sun,
#moon,
#cloud {
  transition-property: all;
  transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
  transition-duration: 0.25s;
}

/* night sky background */
#toggle:checked + svg #container {
  fill: #2b4360;
}

/* move button to right when checked */
#toggle:checked + svg #button {
  transform: translate(28px, 2.333px);
}

/* show/hide sun and moon based on checkbox state */
#sun {
  opacity: 1;
}

#toggle:checked + svg #sun {
  opacity: 0;
}

#moon {
  opacity: 0;
}

#toggle:checked + svg #moon {
  opacity: 1;
}

/* show or hide background items on checkbox state */
#cloud {
  opacity: 1;
}

#toggle:checked + svg #cloud {
  opacity: 0;
}

#stars {
  opacity: 0;
}

#toggle:checked + svg #stars {
  opacity: 1;
}

.pixel-toggle-label {
  display: inline-block;
  cursor: pointer;
  user-select: none;
}

.pixel-checkbox {
  display: none;
}

.pixel-toggle-track {
  width: 6em;
  height: 3.2em;
  border-radius: 3em;
  background: #0e0f12;
  border: 4px solid #16171d;
  box-shadow:
    inset 0 4px 8px rgba(0, 0, 0, 0.65),
    0 10px 25px rgba(0, 0, 0, 0.45);
  position: relative;
  transition:
    background 0.4s ease,
    border-color 0.4s ease;
}

.indicator-wrapper {
  position: absolute;
  top: 50%;
  width: 0.85em;
  height: 0.85em;
  display: flex;
  justify-content: center;
  align-items: center;
  pointer-events: none;
  transition: all 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.indicator-on-wrap {
  left: 0.9em;
  color: #00ffaa;
  opacity: 0.12;
  transform: translateY(-50%) scale(0.8);
}

.indicator-off-wrap {
  right: 0.9em;
  color: #ff007f;
  opacity: 0.7;
  transform: translateY(-50%) scale(1.1);
  filter: drop-shadow(0 0 3px rgba(255, 0, 127, 0.4));
}

.pixel-coin-thumb {
  width: 2.45em;
  height: 2.45em;
  border-radius: 50%;
  background: #ff007f;
  border: 3.5px solid #16171d;
  position: absolute;
  top: 0.12em;
  left: 0.12em;
  box-shadow:
    inset 0 3px 0 rgba(255, 255, 255, 0.28),
    inset 0 -3px 0 rgba(0, 0, 0, 0.28),
    0 4px 8px rgba(0, 0, 0, 0.45),
    0 0 15px rgba(255, 0, 127, 0.35);
  display: flex;
  justify-content: center;
  align-items: center;
  overflow: hidden;
  transform: translate3d(0, 0, 0) rotate(0deg);
  transition:
    transform 0.5s cubic-bezier(0.34, 1.56, 0.64, 1),
    background 0.4s ease,
    box-shadow 0.4s ease;
}

.pixel-coin-thumb::after {
  content: "";
  position: absolute;
  top: 0;
  left: -130%;
  width: 60%;
  height: 100%;
  background: linear-gradient(
    90deg,
    rgba(255, 255, 255, 0) 0%,
    rgba(255, 255, 255, 0.32) 50%,
    rgba(255, 255, 255, 0) 100%
  );
  transform: skewX(-25deg);
  transition: left 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.face-svg {
  position: absolute;
  width: 1.35em;
  height: 1.35em;
  color: #16171d;
  transition: all 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
  pointer-events: none;
  z-index: 2;
}

.face-sad {
  opacity: 1;
  transform: rotate(0deg) scale(1);
}

.face-happy {
  opacity: 0;
  transform: rotate(180deg) scale(0.7);
}

.pixel-checkbox:checked ~ .pixel-toggle-track {
  background: #0b120f;
  border-color: #131715;
}

.pixel-checkbox:checked ~ .pixel-toggle-track .indicator-on-wrap {
  opacity: 0.85;
  transform: translateY(-50%) scale(1.15) rotate(5deg);
  filter: drop-shadow(0 0 4px rgba(0, 255, 170, 0.5));
}

.pixel-checkbox:checked ~ .pixel-toggle-track .indicator-off-wrap {
  opacity: 0.1;
  transform: translateY(-50%) scale(0.8) rotate(-5deg);
  filter: none;
}

.pixel-checkbox:checked ~ .pixel-toggle-track .pixel-coin-thumb {
  transform: translate3d(2.83em, 0, 0) rotate(360deg);
  background: #00ffaa;
  box-shadow:
    inset 0 3px 0 rgba(255, 255, 255, 0.32),
    inset 0 -3px 0 rgba(0, 0, 0, 0.22),
    0 4px 8px rgba(0, 0, 0, 0.45),
    0 0 18px rgba(0, 255, 170, 0.5);
}

.pixel-checkbox:checked ~ .pixel-toggle-track .pixel-coin-thumb::after {
  left: 130%;
}

.pixel-checkbox:checked ~ .pixel-toggle-track .face-sad {
  opacity: 0;
  transform: rotate(-180deg) scale(0.7);
}

.pixel-checkbox:checked ~ .pixel-toggle-track .face-happy {
  opacity: 1;
  transform: rotate(0deg) scale(1);
}

.pixel-toggle-label:hover .pixel-coin-thumb {
  transform: translate3d(0, 0, 0) rotate(0deg) scale(1.06);
}

.pixel-checkbox:checked ~ .pixel-toggle-track:hover .pixel-coin-thumb {
  transform: translate3d(2.83em, 0, 0) rotate(360deg) scale(1.06);
}

.pixel-toggle-label:active .pixel-coin-thumb {
  transform: translate3d(0, 0, 0) rotate(0deg) scale(0.92);
}

.pixel-checkbox:checked ~ .pixel-toggle-track:active .pixel-coin-thumb {
  transform: translate3d(2.83em, 0, 0) rotate(360deg) scale(0.92);
}

